"""Small cashflow analytics: NPV and IRR (stdlib only).

Conventions
-----------
- ``cashflows`` are indexed by period: cashflows[0] is at t=0,
  cashflows[1] at t=1, and so on.
- NPV uses the discount factor (1 + rate) ** -t.
- IRR solves npv(r, cashflows) == 0 via Newton's method on the NPV
  (using its analytic derivative), with a bisection fallback on the
  bracket (-0.99, 10.0).
"""

from __future__ import annotations

from typing import Sequence


def npv(rate: float, cashflows: Sequence[float]) -> float:
    """Net present value of cashflows at t=0,1,2,... discounted at ``rate``."""
    return sum(cf / (1.0 + rate) ** t for t, cf in enumerate(cashflows))


def _npv_derivative(rate: float, cashflows: Sequence[float]) -> float:
    """d(npv)/d(rate) = sum(-t * cf / (1+rate)**(t+1))."""
    return sum(
        -t * cf / (1.0 + rate) ** (t + 1) for t, cf in enumerate(cashflows)
    )


def _has_sign_change(cashflows: Sequence[float]) -> bool:
    signs = [1 if cf > 0 else -1 if cf < 0 else 0 for cf in cashflows]
    signs = [s for s in signs if s != 0]
    return any(signs[i] != signs[i - 1] for i in range(1, len(signs)))


def irr(cashflows: Sequence[float]) -> float:
    """Internal rate of return via Newton's method with bisection fallback.

    Raises ValueError if no sign change exists in the cashflows or no root
    can be found.
    """
    n = len(cashflows)
    if n < 2:
        raise ValueError("need at least two cashflows")
    if not _has_sign_change(cashflows):
        raise ValueError("cashflows must contain at least one sign change")

    # Newton's method on f(r) = npv(r), f'(r) = d(npv)/dr.
    r = 0.1
    for _ in range(50):
        f = npv(r, cashflows)
        fp = _npv_derivative(r, cashflows)
        if fp == 0.0:
            break
        step = f / fp
        r_new = r - step
        if abs(step) < 1e-14:
            return r_new
        r = r_new
        if not (-1e6 < r < 1e6):  # diverged
            break
    else:
        pass  # fell through after 50 iterations; check residual below

    if abs(npv(r, cashflows)) < 1e-9:
        return r

    # Bisection fallback on (-0.99, 10.0).
    lo, hi = -0.99, 10.0
    f_lo = npv(lo, cashflows)
    f_hi = npv(hi, cashflows)
    if f_lo * f_hi > 0:
        raise ValueError("IRR not bracketed in (-0.99, 10.0)")
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        f_mid = npv(mid, cashflows)
        if abs(f_mid) < 1e-14:
            return mid
        if f_lo * f_mid <= 0:
            hi = mid
        else:
            lo, f_lo = mid, f_mid
    return 0.5 * (lo + hi)

